// Generates the flavor SDK version constants and the flavors' splitio_commons
// constraints from the pubspec `version:` lines.
//
// Usage: dart run scripts/sync_sdk_versions.dart [--check]
//   (no flag)  rewrite out-of-sync files, print each updated path to stdout
//   --check    write nothing, print out-of-sync paths to stderr, exit 1 if any
import 'dart:io';

const _header =
    '// GENERATED by scripts/sync_sdk_versions.dart from pubspec.yaml — do not edit.';

/// Flavor package directory -> SDK identifier prefix.
const _flavors = {
  'splitio_client_side': 'dart_st',
  'splitio_server_side': 'dart_mt',
};

final _versionRe = RegExp(r'^version:\s*(\S+)', multiLine: true);
final _commonsRe = RegExp(r'^(\s*splitio_commons:\s*)\^\S+', multiLine: true);

String readVersion(String pubspec) {
  final match = _versionRe.firstMatch(pubspec);
  if (match == null) throw StateError('No version: line found in pubspec');
  return match.group(1)!;
}

String versionDartContent(String prefix, String version) => '$_header\n'
    '/// SDK identifier sent in the SplitSDKVersion header and impression '
    'metadata.\n'
    "const String sdkVersion = '$prefix-$version';\n";

String pubspecWithCommons(String pubspec, String commonsVersion) =>
    pubspec.replaceFirstMapped(
      _commonsRe,
      (m) => '${m.group(1)}^$commonsVersion',
    );

void main(List<String> args) {
  final check = args.contains('--check');
  final root = File.fromUri(Platform.script).parent.parent.path;
  String abs(String rel) => '$root/$rel';

  final commonsVersion = readVersion(
      File(abs('packages/splitio_commons/pubspec.yaml')).readAsStringSync());

  final expected = <String, String>{};
  _flavors.forEach((dir, prefix) {
    final pubspecPath = 'packages/$dir/pubspec.yaml';
    final pubspec = File(abs(pubspecPath)).readAsStringSync();
    expected['packages/$dir/lib/src/version.dart'] =
        versionDartContent(prefix, readVersion(pubspec));
    expected[pubspecPath] = pubspecWithCommons(pubspec, commonsVersion);
  });
  // packages/e2e depends on the flavors via path, so it needs no syncing.

  final stale = <String>[];
  expected.forEach((path, content) {
    final file = File(abs(path));
    if (file.existsSync() && file.readAsStringSync() == content) return;
    stale.add(path);
    if (!check) file.writeAsStringSync(content);
  });

  if (check) {
    if (stale.isNotEmpty) {
      stale.forEach(stderr.writeln);
      exit(1);
    }
  } else {
    stale.forEach(stdout.writeln);
  }
}
